import 'dart:async';

import 'package:flame_audio/flame_audio.dart';
import 'package:flutter/foundation.dart';

/// Short sound effects. Every file is original and generated by
/// `tool/generate_sounds.py`.
enum Sfx {
  punch('punch.wav', pooled: true),
  kick('kick.wav', pooled: true),
  hit('hit.wav', pooled: true),
  block('block.wav', pooled: true),
  jump('jump.wav', pooled: true),
  land('land.wav', pooled: true),
  tap('tap.wav', pooled: true),
  powerCharge('power_charge.wav'),
  powerWeb('power_web.wav'),
  powerDash('power_dash.wav'),
  powerBeam('power_beam.wav'),
  powerStomp('power_stomp.wav'),
  powerPlasma('power_plasma.wav'),
  ready('ready.wav'),
  fight('fight.wav'),
  ko('ko.wav'),
  victory('victory.wav'),
  defeat('defeat.wav');

  const Sfx(this.file, {this.pooled = false});

  final String file;

  /// Frequent sounds use a small pool of players so rapid button mashing
  /// stays responsive.
  final bool pooled;
}

/// Background music loops.
enum Music {
  menu('music_menu.wav'),
  battle('music_battle.wav');

  const Music(this.file);
  final String file;
}

/// Plays all game sound. Silent until [init] is called (tests never call
/// it), and every call is fail-safe: audio problems never crash the game.
class GameAudio {
  GameAudio._();

  static final GameAudio instance = GameAudio._();

  /// Kept moderate on purpose: the game is for young children.
  static const double musicVolume = 0.32;
  static const double sfxVolume = 0.75;

  bool _ready = false;
  final Map<Sfx, AudioPool> _pools = {};
  Music? _music;

  /// Whether sound is switched off by the player.
  final ValueNotifier<bool> muted = ValueNotifier(false);

  Future<void> init() async {
    try {
      await FlameAudio.bgm.initialize();
      await FlameAudio.audioCache.loadAll([
        for (final s in Sfx.values) s.file,
        for (final m in Music.values) m.file,
      ]);
      for (final s in Sfx.values.where((s) => s.pooled)) {
        _pools[s] = await FlameAudio.createPool(s.file, maxPlayers: 3);
      }
      _ready = true;
    } catch (e) {
      debugPrint('Audio unavailable: $e');
    }
  }

  void play(Sfx sfx, {double volume = 1}) {
    if (!_ready || muted.value) return;
    final v = (sfxVolume * volume).clamp(0.0, 1.0);
    final pool = _pools[sfx];
    unawaited(
      _guard(
        () => pool != null
            ? pool.start(volume: v)
            : FlameAudio.play(sfx.file, volume: v),
      ),
    );
  }

  /// Starts a music loop, unless it is already playing.
  void playMusic(Music music) {
    if (_music == music && FlameAudio.bgm.isPlaying) return;
    _music = music;
    if (!_ready || muted.value) return;
    unawaited(
      _guard(() => FlameAudio.bgm.play(music.file, volume: musicVolume)),
    );
  }

  void stopMusic() {
    _music = null;
    if (!_ready) return;
    unawaited(_guard(FlameAudio.bgm.stop));
  }

  void toggleMute() {
    muted.value = !muted.value;
    if (!_ready) return;
    if (muted.value) {
      unawaited(_guard(FlameAudio.bgm.pause));
    } else if (_music != null) {
      unawaited(
        _guard(() => FlameAudio.bgm.play(_music!.file, volume: musicVolume)),
      );
    }
  }

  Future<void> _guard(Future<Object?> Function() action) async {
    try {
      await action();
    } catch (e) {
      debugPrint('Audio error: $e');
    }
  }
}
